    61	fn publish_channel(style_attr: &str, channel: PaintChannel, expected: f64) {
    62	    let source = format!(
    63	        "<svg><pattern id=\"p\"/><path style=\"{style_attr}\" d=\"M0 0 L1 1 2 3 Z\"/></svg>"
    64	    );
    65	    let doc = LexicalDocument::parse(Arc::new(source.into_bytes()), 1 << 20, &mut Run).unwrap();
    66	    let mut shared = DecodeSource::new(&doc, &mut Run).unwrap();
    67	    let mut builder = SceneBuilder::new(
    68	        doc.source_owner().clone(), animation(doc.source_owner()), 7, viewport(), Limits::default(),
    69	    ).unwrap();
    70	    let root = builder.root_id();
    71	    let draft = builder.begin_draft(root).unwrap();
    72	    let path_start = doc.source().windows(6).position(|w| w == b"<path ").unwrap();
    73	    let path_end = path_start + doc.source()[path_start..].windows(2).position(|w| w == b"/>").unwrap() + 2;
    74	    let mut input = shape(doc.source());
    75	    input.shape.source.element = Span { start: path_start, end: path_end };
    76	    let shape_id = builder.append_shape(root, input, &mut Run).unwrap();
    77	    let pattern_element = element(&doc, b"pattern");
    78	    let owner = builder.definition_owner(
    79	        &draft, &shared, pattern_element, DefinitionTarget::Shape(shape_id), &mut Run,
    80	    ).unwrap();
    81	    let style = shared.compute_style(element(&doc, b"path"), None, &mut Run).unwrap();
    82	    let bounds = [0., 0., 10., 10.];
    83	    let mut active = ActiveDefinitions::default();
    84	    let mut ledger = ChargeLedger::new(doc.source_owner(), 1 << 20, 65536).unwrap();
    85	    let mut ctx = DefinitionContext { shared: &mut shared, builder: &mut builder, scene: root, active: &mut active, ledger: &mut ledger };
    86	    let plan = plan_production_pattern(
    87	        &mut ChannelPlanner, &mut ctx, pattern_element, owner, channel, identity(), bounds, &style, &mut Run,
    88	    ).unwrap();
    89	    let ProductionDefinitionPlan::Pattern { plan, mapping } = plan else { panic!("pattern mapping required") };
    90	    assert_eq!(mapping.opacity, expected);
    91	    let DefinitionDescriptor::Pattern(descriptor) = plan.descriptor else { panic!("pattern descriptor required") };
    92	    drop(plan);
    93	    drop(ctx);
    94	
    95	    let child = builder.new_scene(viewport()).unwrap();
    96	    builder.seal(child, &mut Run).unwrap();
    97	    let mut job = RasterJob::new(ChargeLedger::new(doc.source_owner(), 1 << 20, 65536).unwrap()).unwrap();
    98	    let mut tickets = PatternTickets::new().unwrap();
    99	    let request = tickets.request_mapped(
   100	        &builder, &draft, &DecodeSource::new(&doc, &mut Run).unwrap(), child,
   101	        descriptor, mapping, shape_id, channel, &job, &mut Run,
   102	    ).unwrap();
   103	    let ticket = request.ticket;
   104	    let pixels = job.buffer(RasterPool::Output, 16, &mut Run).unwrap();
   105	    job.reserve(pixels, 4, &mut Run).unwrap();
   106	    job.extend(pixels, &[1, 2, 3, 255], &mut Run).unwrap();
   107	    let output = JobRenderOutput { generation: 7, pixels, width: 1, height: 1, stride: 4 };
   108	    let (pattern_id, paint_index) = tickets.complete_mapped(
   109	        ticket, &mut builder, &draft, &mut job, Ok(output), &mut Run,
   110	    ).unwrap();
   111	    let view = builder.scene(root).unwrap();
   112	    let paint = match channel {
   113	        PaintChannel::Fill => &view.fill_paints[paint_index],
   114	        PaintChannel::Stroke => &view.stroke_paints[paint_index],
   115	    };
   116	    assert_eq!(paint.pattern, Some(pattern_id));
   117	    assert_eq!(paint.pattern_opacity, expected);
   118	    assert_eq!(view.pattern(pattern_id).unwrap().tile.rgba(), &[1, 2, 3, 255]);
   119	    let shape = view.shape(shape_id).unwrap();
   120	    assert_eq!(match channel { PaintChannel::Fill => shape.fill_paint, PaintChannel::Stroke => shape.stroke_paint }, Some(paint_index));
   121	    builder.commit_draft(&draft, &mut Run).unwrap();
   122	    assert!(builder.freeze().is_ok());
   123	}
