138	impl<'src, 'ctx> ResolveContext<'src, 'ctx> {
139	    pub fn validate(&self) -> Result<()> {
140	        if !std::sync::Arc::ptr_eq(self.shared.source_owner(), self.ledger.source_owner()) {
141	            return Err(invalid(0));
142	        }
143	        Ok(())
144	    }
145	    /// Validate owned cached entries against the same immutable source. Source
146	    /// witnesses share the original Arc allocation and keep it alive; equal
147	    /// source bytes in a different allocation do not authorize a cache hit.
148	    pub fn validate_cache(&self, control: &mut dyn WorkControl) -> Result<()> {
149	        self.validate()?;
150	        control.checkpoint().map_err(stopped)?;
151	        self.cache.storage_bytes_controlled(control)?;
152	        for entry in &self.cache.entries {
153	            control.charge(WorkKind::PaintVisit, 1).map_err(stopped)?;
154	            if !std::sync::Arc::ptr_eq(&entry.source, self.shared.source_owner())
155	                || !self
156	                    .shared
157	                    .tokens()
158	                    .get(entry.definition.0)
159	                    .is_some_and(|token| {
160	                        matches!(
161	                            token.kind,
162	                            TokenKind::StartElement | TokenKind::EmptyElement
163	                        )
164	                    })
165	                || !entry
166	                    .context
167	                    .viewport
168	                    .into_iter()
169	                    .all(|v| v.is_finite() && v > 0.)
170	                || !vexel_geometry::affine_valid(entry.context.user_inverse)
171	                || !entry.context.bounds.into_iter().all(f64::is_finite)
172	                || entry.context.bounds[0] > entry.context.bounds[2]
173	                || entry.context.bounds[1] > entry.context.bounds[3]
174	                || entry.stop_range != entry.paint.stops
175	            {
176	                return Err(invalid(0));
177	            }
178	            let stops = entry
179	                .stop_range
180	                .slice(&entry.stops)
181	                .ok_or_else(|| invalid(0))?;
182	            let mut previous = 0.;
183	            for stop in stops {
184	                control.charge(WorkKind::PaintVisit, 1).map_err(stopped)?;
185	                if !stop.offset.is_finite()
186	                    || !(0.0..=1.0).contains(&stop.offset)
187	                    || stop.offset < previous
188	                {
189	                    return Err(invalid(0));
190	                }
191	                previous = stop.offset;
192	            }
193	        }
194	        for slot in &self.cache.slots {
195	            control
196	                .charge(WorkKind::ReferenceProbe, 1)
197	                .map_err(stopped)?;
198	            if slot.is_some_and(|index| index >= self.cache.entries.len()) {
199	                return Err(invalid(0));
200	            }
201	        }
202	        Ok(())
203	    }
204	}
