143	pub(crate) fn validate_production_post(
144	    ctx: &DefinitionContext<'_, '_>,
145	    kind: DefinitionKind,
146	    flavor: Option<DecodeFlavor>,
147	    post: PostOperation,
148	    control: &mut dyn WorkControl,
149	) -> Result<()> {
150	    let view = ctx.builder.scene(ctx.scene)?;
151	    match post {
152	        PostOperation::AttachTargetedMask(target)
153	            if kind == DefinitionKind::Mask && flavor.is_none_or(|f| f == DecodeFlavor::Mask) =>
154	        {
155	            target.validate(ctx, control)
156	        }
157	        PostOperation::AttachTargetedMask(_) | PostOperation::AttachMask(_) => Err(invalid(0)),
158	        PostOperation::AttachClip(id)
159	            if kind == DefinitionKind::Clip && view.clip(id).is_some() =>
160	        {
161	            Ok(())
162	        }
163	        PostOperation::FinishPattern if kind == DefinitionKind::Pattern => Ok(()),
164	        PostOperation::FinishMarker if kind == DefinitionKind::Marker => Ok(()),
165	        PostOperation::FinishGroup(id) if view.group(id).is_some() => Ok(()),
166	        PostOperation::None => Ok(()),
167	        _ => Err(invalid(0)),
168	    }
169	}
343	fn validate_production_plan<'src>(
344	    ctx: &mut DefinitionContext<'src, '_>,
345	    kind: DefinitionKind,
346	    element: ElementId,
347	    owner: DefinitionOwner,
348	    transform: Affine,
349	    bounds: [f64; 4],
350	    style: &CssPaint<'src>,
351	    control: &mut dyn WorkControl,
352	    plan: impl FnOnce(&mut DefinitionContext<'src, '_>, &mut dyn WorkControl) -> Result<ProductionDefinitionPlan<'src>>,
353	) -> Result<ProductionDefinitionPlan<'src>> {
354	    owner.validate(ctx)?;
355	    validate_style(ctx.shared.source(), style, control)?;
356	    ctx.shared
357	        .element(element, crate::memory::add(element.0, 1)?, control)?;
358	    if !vexel_geometry::affine_valid(transform)
359	        || !bounds.into_iter().all(f64::is_finite)
360	        || bounds[2] < 0.
361	        || bounds[3] < 0.
362	    {
363	        return Err(invalid(0));
364	    }
365	    let plan = plan(ctx, control)?;
366	    let (definition, mapping) = match &plan {
367	        ProductionDefinitionPlan::Definition(plan) => (plan, None),
368	        ProductionDefinitionPlan::Pattern { plan, mapping } => (plan, Some(*mapping)),
369	    };
370	    let actual = match &definition.descriptor {
371	        DefinitionDescriptor::Clip(_) => DefinitionKind::Clip,
372	        DefinitionDescriptor::Mask(_) => DefinitionKind::Mask,
373	        DefinitionDescriptor::Pattern(descriptor) => {
374	            if descriptor.definition != element {
375	                return Err(invalid(0));
376	            }
377	            let map = mapping.ok_or_else(|| invalid(0))?;
378	            map.pixel_inverse(*descriptor)?;
379	            let DefinitionTarget::Shape(shape) = owner.target else {
380	                return Err(invalid(0));
381	            };
382	            if ctx
383	                .builder
384	                .scene(ctx.scene)?
385	                .shape(shape)
386	                .ok_or_else(|| invalid(0))?
387	                .source
388	                != map.source_map
389	                || map.bounds != bounds
390	            {
391	                return Err(invalid(0));
392	            }
393	            DefinitionKind::Pattern
394	        }
395	        DefinitionDescriptor::Marker(_) => DefinitionKind::Marker,
396	        DefinitionDescriptor::Filter { filter, primitives } => {
397	            let DefinitionTarget::Group(_) = owner.target else {
398	                return Err(invalid(0));
399	            };
400	            crate::validate::filter(*filter, primitives, control)?;
401	            for p in primitives {
402	                control.charge(WorkKind::FilterPixel, 1).map_err(stopped)?;
403	                if p.source_offset > ctx.shared.source().len() {
404	                    return Err(invalid(p.source_offset));
405	                }
406	            }
407	            DefinitionKind::Filter
408	        }
409	    };
410	    if actual != kind || (kind != DefinitionKind::Pattern && mapping.is_some()) {
411	        return Err(invalid(0));
412	    }
413	    crate::mask_post::validate_production_post(ctx, kind, None, definition.post, control)?;
414	    if definition.expansions.len() > 65536 {
415	        return Err(crate::types::limit(LimitKind::References));
416	    }
417	    for expansion in &definition.expansions {
418	        crate::mask_post::validate_production_post(
419	            ctx,
420	            kind,
421	            Some(expansion.flavor),
422	            expansion.post,
423	            control,
424	        )?;
425	        control
426	            .charge(WorkKind::ReferenceProbe, 1)
427	            .map_err(stopped)?;
428	        expansion.range.require(ctx.shared.tokens().len(), 0)?;
429	        validate_style(ctx.shared.source(), &expansion.style, control)?;
430	        if !vexel_geometry::affine_valid(expansion.transform)
431	            || !expansion
432	                .viewport
433	                .into_iter()
434	                .all(|v| v.is_finite() && v > 0.)
435	        {
436	            return Err(invalid(0));
437	        }
438	    }
439	    control.checkpoint().map_err(stopped)?;
440	    Ok(plan)
441	}
